def set_stat_headers(self, stat_result: os.stat_result) -> None:
    content_length = str(stat_result.st_size)
    last_modified = formatdate(stat_result.st_mtime, usegmt=True)
    etag_base = str(stat_result.st_mtime) + "-" + str(stat_result.st_size)
    etag = f'"{md5_hexdigest(etag_base.encode(), usedforsecurity=False)}"'
    self.headers.setdefault("content-length", content_length)
    self.headers.setdefault("last-modified", last_modified)
    self.headers.setdefault("etag", etag)

def _should_use_range(self, http_if_range: str) -> bool:
    return http_if_range == self.headers.get("last-modified") or http_if_range == self.headers.get("etag")

@staticmethod
def _parse_range_header(http_range: str, file_size: int) -> list[tuple[int, int]]:
    try:
        units, range_ = http_range.split("=", 1)
    except ValueError:
        raise MalformedRangeHeader()

    units = units.strip().lower()

    if units != "bytes":
        raise MalformedRangeHeader("Only support bytes range")

    ranges = [
        (
            int(_[0]) if _[0] else file_size - int(_[1]),
            int(_[1]) + 1 if _[0] and _[1] and int(_[1]) < file_size else file_size,
        )
        for _ in _RANGE_PATTERN.findall(range_)
        if _ != ("", "")
    ]

    if len(ranges) == 0:
        raise MalformedRangeHeader("Range header: range must be requested")

    if any(not (0 <= start < file_size) for start, _ in ranges):
        raise RangeNotSatisfiable(file_size)

    if any(start > end for start, end in ranges):
        raise MalformedRangeHeader("Range header: start must be less than end")

    if len(ranges) == 1:
        return ranges

    result: list[tuple[int, int]] = []
    for start, end in sorted(ranges):
        for p in range(len(result)):
            p_start, p_end = result[p]
            if start > p_end:
                continue
            elif end < p_start:
                result.insert(p, (start, end))
                break
            else:
                result[p] = (min(start, p_start), max(end, p_end))
                break
        else:
            result.append((start, end))

    return result

def generate_multipart(self, ranges: typing.Sequence[tuple[int, int]], boundary: str, max_size: int, content_type: str) -> tuple[int, typing.Callable[[int, int], bytes]]:
    boundary_len = len(boundary)
    static_header_part_len = 42 + boundary_len + len(content_type) + len(str(max_size))
    content_length = sum(
        (len(str(start)) + len(str(end - 1)) + static_header_part_len)
        + (end - start)
        for start, end in ranges
    ) + (
        5 + boundary_len
    )
    return (
        content_length,
        lambda start, end: (
            f"--{boundary}\n"
            f"Content-Type: {content_type}\n"
            f"Content-Range: bytes {start}-{end-1}/{max_size}\n"
            "\n"
        ).encode("latin-1"),
    )
